const $ = (s, root = document) => root.querySelector(s);
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons = {book:'<path d="M12 5c-3-2-7-2-10-1v15c3-1 7-1 10 1 3-2 7-2 10-1V4c-3-1-7-1-10 1Z"/><path d="M12 5v15"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',tablet:'<rect x="2" y="4" width="20" height="16" rx="2"/><path d="M18 11v2"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M17 5a3 3 0 0 1 0 6m1 4a5 5 0 0 1 3 5"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',back:'<path d="M19 12H5m5-5-5 5 5 5"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',mic:'<rect x="9" y="2" width="6" height="13" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3m-4 0h8"/>',cloud:'<path d="M6 18a5 5 0 1 1 1-10 6 6 0 0 1 11-1 5 5 0 0 1 0 11H6Z"/><path d="m9 12 3 3 4-4"/>',chevron:'<path d="m9 5 7 7-7 7"/>',down:'<path d="m6 9 6 6 6-6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4"/>',play:'<path d="m8 5 11 7-11 7Z" fill="currentColor" stroke="none"/>',pause:'<path d="M9 5v14M15 5v14" stroke-width="3"/>',bookmark:'<path d="M6 3h12v19l-6-4-6 4V3Z"/>',check:'<path d="m5 12 4 4L20 5"/>',edit:'<path d="m16 3 5 5-12 12-6 1 1-6L16 3ZM13 6l5 5"/>',info:'<circle cx="12" cy="12" r="10"/><path d="M12 11v6m0-11v1"/>',share:'<circle cx="18" cy="5" r="3"/><circle cx="6" cy="12" r="3"/><circle cx="18" cy="19" r="3"/><path d="m9 11 6-4M9 13l6 4"/>',print:'<path d="M6 8V2h12v6M6 17H2V8h20v9h-4M6 14h12v8H6V14Z"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>'};
const icon = n => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n] || icons.book}</svg>`;
const people = {
 emma:{name:'Emma Chen',role:'Album owner',initial:'E',pin:'1111',group:'owner'},
 mei:{name:'Mei Chen',role:'Family · Mum',initial:'M',pin:'2468',group:'family'},
 wei:{name:'Wei Chen',role:'Family · Dad',initial:'W',pin:'2469',group:'family'},
 lihua:{name:'Lihua Chen',role:'Family · Grandma',initial:'L',pin:'2470',group:'family'},
 alex:{name:'Alex Morgan',role:'Selected friend',initial:'A',pin:'1357',group:'friends'},
 sophie:{name:'Sophie Lee',role:'Selected friend',initial:'S',pin:'1358',group:'friends'},
 daniel:{name:'Daniel Kim',role:'Selected friend',initial:'D',pin:'1359',group:'friends'}
};
const memberIds=group=>Object.keys(people).filter(id=>people[id].group===group);
const viewerDevice=id=>people[id]?.group==='friends'?'friends':'family';
const deviceNames = {family:'Family living room iPad',friends:"Friends’ shared iPad"};
const assets = [
 {id:'cake',src:'assets/cake.jpg',alt:'Birthday cake with candles',title:'Make a little wish'},
 {id:'family',src:'assets/family.jpg',alt:'Family sharing a moment together',title:'Together again'},
 {id:'birthday',src:'assets/birthday.jpg',alt:'Celebration cake and sweet treats',title:'A table full of love'},
 {id:'graduation',src:'assets/graduation.jpg',alt:'Graduates celebrating on campus',title:'We did it'},
 {id:'campus',src:'assets/campus.jpg',alt:'University campus and a new chapter',title:'Where it all began'},
 {id:'friends',src:'assets/friends.jpg',alt:'Friends together outdoors',title:'The people who made it home'},
 {id:'home',src:'assets/home.jpg',alt:'A quiet moment in a green landscape',title:'A little closer to home'},
 {id:'travel',src:'assets/travel.jpg',alt:'An open landscape to remember',title:'The long way home'}
];
const initialState = () => ({version:1,albums:[
 {id:'birthday',title:'My Birthday',date:'2026-09-12',theme:'Family, Birthday, Home',description:'Another year older. A little closer to the people who matter.',audience:'family',recipients:memberIds('family'),devices:['family'],favorite:true,photos:[
 {...assets[0],caption:'My first birthday back home in two years. Having everyone around the same table made this wish feel different.',audio:null,voice:true},
 {...assets[1],caption:'Mum insisted on one more photograph. Now it is the one I keep coming back to.',audio:null,voice:true},
 {...assets[2],caption:'We stayed at the table long after the candles went out. I wish I could bottle that feeling.',audio:null,voice:false}],contributions:[{id:'c1',photo:0,author:'mei',text:'I made your favourite cake, just like when you were little. Having you home was the best gift for all of us.',status:'pending',audio:null,voice:true}],bookmarks:[]},
 {id:'graduation',title:'Graduation 2026',date:'2026-08-20',theme:'Graduation, Friends, Melbourne',description:'The end of one chapter, and all the people who helped me write it.',audience:'friends',recipients:memberIds('friends'),devices:['friends'],favorite:false,photos:[
 {...assets[3],caption:'We did it. Through late-night study sessions and homesick days, these friends became my second family.',audio:null,voice:true},
 {...assets[4],caption:'One last walk across campus. It feels strange to say goodbye to somewhere that changed me so much.',audio:null,voice:false},
 {...assets[5],caption:'A promise to keep showing up for each other, wherever we go next.',audio:null,voice:true}],contributions:[],bookmarks:[]},
 {id:'home',title:'Letters to Home',date:'2026-07-05',theme:'Home, Travel, Reflection',description:'Small moments I am keeping just for myself.',audience:'private',recipients:[],devices:[],favorite:false,photos:[{...assets[6],caption:'Some days, home is a place. Other days, it is a voice on the other end of the phone.',audio:null,voice:false},{...assets[7],caption:'Taking the long way home, and finding a little peace along the way.',audio:null,voice:false}],contributions:[],bookmarks:[]}
]});
let data, db, account='emma', view='library', filter='all', query='', currentId=null, photoIndex=0, tabletopDevice='family', modalType=null, draft=null, wizardStep=0, audioDraft=null, audioVoice=false, recorder=null, recordStream=null, recordTimer=null, recordSeconds=0, activeAudio=null, currentPlayButton=null, busy=false;
const uid=()=>crypto.randomUUID ? crypto.randomUUID() : 'id'+Date.now()+Math.random().toString(36).slice(2);
let immersive=false, recordingEpoch=0, recordProcessing=false, recordPhase='idle';
const owner=()=>account==='emma';
const canSee=a=>owner() || (a.audience!=='private' && a.recipients.includes(account));
const canTable=a=>canSee(a)&&a.devices.includes(tabletopDevice);
const album=()=>data.albums.find(a=>a.id===currentId);
const formattedDate=s=>new Date(s+'T12:00:00').toLocaleDateString('en-AU',{day:'numeric',month:'long',year:'numeric'});
const audienceName=a=>a.audience==='private'?'Only me':a.audience==='family'?'Family circle':'Selected friends';
async function init(){
 try {db=await new Promise((resolve,reject)=>{const r=indexedDB.open('keepsake-memory-album',1);r.onupgradeneeded=()=>r.result.createObjectStore('state');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)}); data=await new Promise((resolve,reject)=>{const r=db.transaction('state').objectStore('state').get('albums');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});}catch(e){console.warn('Local persistence unavailable',e)}
 if(!data)data=initialState(); render();
}
async function save(){
 if(!db){toast('Browser storage is unavailable. Keep this tab open or export a backup.');return false;}
 try{await new Promise((resolve,reject)=>{const tx=db.transaction('state','readwrite');tx.objectStore('state').put(data,'albums');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});return true;}catch(e){toast('Could not save on this device. Export a backup before closing.');return false;}
}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4200)}
function wave(){return `<div class="wave" aria-hidden="true">${Array.from({length:38},(_,i)=>`<i style="height:${4+(i*17%19)}px"></i>`).join('')}</div>`}
function audioBlock(a,p,i,contribution=null){const obj=contribution||p;if(!obj.audio&&!obj.voice)return '';return `<div class="audio-box"><button class="play" data-action="play" data-album="${a.id}" data-index="${i}" ${contribution?`data-contribution="${esc(contribution.id)}"`:''} aria-label="Play ${contribution?'contribution':'photo story'}">${icon('play')}</button><div class="audio-info"><b>${contribution?esc(people[obj.author]?.name||obj.author):'The voice behind the memory'}</b>${wave()}<small>${obj.audio?'Recorded voice note':'Demo narration · generated voice'}</small></div>${icon('mic')}</div>`}
function render(){
 stopPlayback();
 document.body.classList.toggle('focus-album',view==='tabletop'&&immersive);
 const count=owner()?data.albums.reduce((n,a)=>n+a.contributions.filter(c=>c.status==='pending').length,0):0;
 const person=people[account];
 $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div><div class="brand">${icon('book')}<span>keepsake<span style="color:var(--coral)">.</span></span></div><div class="brand-sub">A hybrid memory album</div></div><nav class="nav" aria-label="Main navigation">${[['library','grid','My library'],['tabletop','book','Tabletop album'],['connections','users','People & devices'],['guide','info','Guide']].map(([v,i,t])=>`<button data-action="navigate" data-view="${v}" class="${view===v?'active':''}" aria-label="${t}" ${view===v?'aria-current="page"':''}>${icon(i)}${t}${v==='library'&&count?`<span class="dot">${count}</span>`:''}</button>`).join('')}</nav><div class="sidebar-note">${icon('heart')}<br>A little closer,<br>one memory at a time.<br><br><span style="font-size:9px">INTERACTIVE CONCEPT · 2026</span></div></aside><main class="main"><header class="topbar"><div class="crumb">Your space <span style="margin:0 8px">/</span> <b>${({library:'Memory library',tabletop:'The tabletop album',connections:'People & devices',guide:'Your demo companion'})[view]}</b></div><div class="top-actions"><span class="prototype">Local prototype</span><button class="profile" data-action="account" aria-label="Switch demo viewer account"><span class="avatar">${person.initial}</span><span>${person.name}<small>${person.role}</small></span>${icon('down')}</button></div></header>${view==='library'?libraryView():view==='tabletop'?tabletopView():view==='connections'?connectionsView():guideView()}</main></div>`;
 if(view==='library'&&!currentId){const input=$('#search');if(input)input.addEventListener('input',e=>{query=e.target.value;updateGrid()})}
 if(view==='tabletop')$('.tabletop-bar').insertAdjacentHTML('beforeend',`<button class="btn ghost" data-action="focus-mode">${icon('tablet')}${immersive?'Exit focus mode':'Focus mode'}</button>`);
 if(view==='tabletop'&&currentId)attachSwipe();
}
function libraryView(){if(currentId){const a=album();if(a&&canSee(a))return detailView(a);currentId=null;}
 return `<div class="content"><div class="intro-row"><div><div class="eyebrow">The moments that make us</div><h1>Life, lovingly collected.</h1><p>A home for your photographs, your voices, and everything in between.</p></div>${owner()?`<button class="btn primary" data-action="create">${icon('plus')}Create an album</button>`:''}</div><section class="hero" aria-label="Featured album"><div class="hero-copy"><div class="eyebrow">Made for remembering</div><h2>More than a photo.<br>A feeling, kept.</h2><p>Open a page, hear a familiar voice.<br>Bring your memories a little closer.</p><button class="text-link" data-action="navigate" data-view="tabletop">Open the tabletop album ${icon('arrow')}</button></div><div class="hero-art" aria-hidden="true"><div class="polaroid"><span class="tape"></span><img src="assets/family.jpg" alt=""></div><div class="polaroid second"><span class="tape"></span><img src="assets/graduation.jpg" alt=""></div><div class="hero-flower">✳</div></div></section><div class="toolbar"><div class="tabs" role="group" aria-label="Filter albums">${[['all','All memories'],['shared','Shared with others'],['favorites','Favourites']].map(([id,t])=>`<button class="${filter===id?'active':''}" data-action="filter" data-filter="${id}" aria-pressed="${filter===id}">${t}</button>`).join('')}</div><label class="search">${icon('search')}<input id="search" type="search" placeholder="Find a person, place, or moment" aria-label="Search albums" value="${esc(query)}"></label></div><div id="grid-content">${gridContent()}</div><div class="footer-strip"><span>${icon('lock')}Thoughtfully shared. Private by default.</span><span>${icon('cloud')}${db?'Saved in this browser':'Temporary session'} · Cloud connection simulated</span></div></div>`;
}
function matchingAlbums(){return data.albums.filter(a=>canSee(a)&&(filter!=='shared'||a.audience!=='private')&&(filter!=='favorites'||a.favorite)&&`${a.title} ${a.description} ${a.theme} ${a.date} ${a.recipients.map(id=>people[id]?.name).join(' ')} ${a.photos.map(p=>p.caption).join(' ')}`.toLowerCase().includes(query.toLowerCase()))}
function gridContent(){const list=matchingAlbums();return `<div class="section-label"><span>${list.length} ${list.length===1?'ALBUM':'ALBUMS'} · ${owner()?'CURATED BY YOU':'SHARED WITH YOU'}</span><span>Every photo has a story worth keeping</span></div><div class="album-grid">${list.map(a=>albumCard(a)).join('')||`<div class="empty">${icon('book')}<h3 style="margin-top:15px">No memories here yet</h3><p>Try another search or create a new album.</p></div>`}</div>`}
function updateGrid(){$('#grid-content').innerHTML=gridContent()}
function albumCard(a,table=false){return `<article class="album-card"><div class="cover"><button style="width:100%;height:100%;padding:0" data-action="open" data-id="${esc(a.id)}" aria-label="Open ${esc(a.title)}"><img src="${esc(a.photos[0].src)}" alt="${esc(a.photos[0].alt)}"><span class="badge">${icon(a.audience==='private'?'lock':'users')}${audienceName(a)}</span><span class="count">${a.photos.length} photographs · ${a.photos.filter(p=>p.audio||p.voice).length} voice stories</span></button>${!table?`<button class="icon-btn favorite ${a.favorite?'on':''}" data-action="favorite" data-id="${a.id}" aria-label="${a.favorite?'Remove from':'Add to'} favourites" aria-pressed="${a.favorite}">${icon('heart')}</button>`:''}</div><div class="card-title"><button data-action="open" data-id="${a.id}">${esc(a.title)}</button>${!table?`<button class="icon-btn" data-action="open" data-id="${a.id}" aria-label="View ${esc(a.title)}">${icon('chevron')}</button>`:''}</div><div class="card-meta">${formattedDate(a.date)} <span>·</span> ${esc(a.theme.split(',')[0])}</div><div class="card-foot"><span>${icon(a.devices.length?'tablet':'lock')}${a.devices.length?'Tabletop enabled':'Kept in your library'}</span><span>${icon('mic')}${owner()&&a.contributions.some(c=>c.status==='pending')?'New family story':'Stories inside'}</span></div></article>`}
function detailView(a){const p=a.photos[photoIndex]||a.photos[0];photoIndex=Math.max(0,Math.min(photoIndex,a.photos.length-1));const approved=a.contributions.filter(c=>c.status==='approved'&&c.photo===photoIndex);const pending=a.contributions.filter(c=>c.status==='pending');return `<div class="content"><div class="detail-top"><button class="text-link" data-action="back-library">${icon('back')}Back to memories</button><div class="detail-actions">${owner()?`<button class="btn" data-action="share">${icon('share')}Share & devices</button><button class="btn" data-action="edit-album">${icon('edit')}Edit album</button>`:''}<button class="btn" data-action="export">${icon('download')}Export</button>${owner()?`<button class="icon-btn" data-action="delete" aria-label="Delete album">${icon('trash')}</button>`:''}</div></div><div class="intro-row"><div><div class="eyebrow">${audienceName(a)} · ${a.photos.length} photographs</div><h1>${esc(a.title)}</h1><p>${esc(a.description)}</p></div><button class="btn primary" data-action="table-open">${icon('book')}Open as an album</button></div><div class="detail-layout"><section><img class="photo-main" src="${esc(p.src)}" alt="${esc(p.alt)}"><div class="thumb-row" aria-label="Photos in this album">${a.photos.map((p,i)=>`<button class="thumb ${i===photoIndex?'selected':''}" data-action="photo" data-index="${i}" aria-label="Photo ${i+1}: ${esc(p.title)}" aria-pressed="${i===photoIndex}"><img src="${esc(p.src)}" alt="${esc(p.alt)}"></button>`).join('')}</div><p class="story-date">${formattedDate(a.date)} · Photograph ${photoIndex+1} of ${a.photos.length}</p>${a.theme.split(',').map(t=>`<span class="tag">${esc(t.trim())}</span>`).join('')}</section><section><div class="story-heading"><span class="eyebrow">The story behind it</span>${owner()?`<button class="icon-btn" data-action="edit-story" aria-label="Edit photo story">${icon('edit')}</button>`:''}</div><h2 style="margin-top:12px">${esc(p.title)}</h2><p class="story-copy">${esc(p.caption||'Every photograph is the beginning of a story.')}</p>${audioBlock(a,p,photoIndex)}<section class="story-section"><div class="story-heading"><span class="eyebrow">Other voices, same memory</span><button class="text-link" data-action="contribute">${icon('plus')}Add yours</button></div>${approved.map(c=>contributionHTML(a,c)).join('')||'<p class="muted" style="font-size:12px;line-height:1.8;margin-top:15px">A different perspective can make a memory even richer. Invite someone to tell their side of the story.</p>'}</section>${owner()&&pending.length?`<section class="story-section panel" style="padding:18px"><span class="eyebrow">${pending.length} ${pending.length===1?'story':'stories'} waiting for you</span>${pending.map(c=>contributionHTML(a,c,true)).join('')}</section>`:''}</section></div><div class="footer-strip"><span>${icon('lock')}${a.recipients.length?`Visible to you and ${a.recipients.map(id=>people[id]?.name||id).map(esc).join(', ')}`:'Only you can view this album'}</span><span>${icon('cloud')}Local prototype · Changes carry into tabletop view</span></div></div>`}
function contributionHTML(a,c,review=false){return `<article class="contribution"><small>${esc(people[c.author]?.name||c.author)} · ${review?'Awaiting your approval':c.author==='mei'?'Mum’s perspective':'Another perspective'}${review?` · Photo ${c.photo+1}`:''}</small><p>${esc(c.text)}</p>${audioBlock(a,null,c.photo,c)}${review?`<div class="action-row" style="margin-top:12px"><button class="btn primary" data-action="approve" data-contribution="${c.id}">${icon('check')}Approve</button><button class="btn" data-action="decline" data-contribution="${c.id}">Decline</button></div>`:view!=='tabletop'&&(owner()||c.author===account)?`<button class="text-link" style="font-size:9px;margin-top:10px" data-action="withdraw" data-contribution="${c.id}">${c.author===account?'Withdraw story':'Remove from album'}</button>`:''}</article>`}
function tabletopView(){let a=album();if(a&&!canTable(a)){currentId=null;a=null}const deviceOptions=owner()?Object.entries(deviceNames):[[viewerDevice(account),deviceNames[viewerDevice(account)]]];
 return `<div class="tabletop"><div class="tabletop-bar">${a?`<button class="btn ghost" data-action="table-library">${icon('back')}Album shelf</button>`:`<span class="eyebrow">A familiar place to return to</span>`}<div class="device-status">${icon('tablet')}<label><span class="sr-input">Display device</span><select id="device-select" aria-label="Display device" style="background:transparent;border:0;color:inherit;font:inherit;max-width:210px">${deviceOptions.map(([id,n])=>`<option value="${id}" ${tabletopDevice===id?'selected':''}>${n}</option>`).join('')}</select></label><span class="status-dot"></span></div><button class="btn ghost" data-action="account">${icon('lock')}Switch viewer</button></div><div class="notice-bar">Demo viewer: <b>${people[account].name}</b> · Showing albums allowed for this viewer <em>and</em> this display. PINs and cloud connection are simulated; all data stays in this browser.</div>${a?bookView(a):`<div class="tabletop-title"><div class="eyebrow">${people[account].group==='family'?'Family circle':people[account].group==='friends'?'A chapter with friends':'Your connected display'}</div><h1>Pull up a memory.</h1><p>Some stories are better shared, side by side.</p></div><div class="album-grid">${data.albums.filter(canTable).map(a=>albumCard(a,true)).join('')||`<div class="empty"><h3>A blank page, for now.</h3><p>No albums have been shared with this viewer and display.<br>In the owner’s library, open Share & devices to allow an album.</p></div>`}</div><p class="book-hint" style="margin-top:32px">${icon('lock')} Only memories shared with ${esc(people[account].name)} and authorised for this display appear here.</p>`}</div>`}
function bookView(a){const p=a.photos[photoIndex];const marked=a.bookmarks.some(b=>b.account===account&&b.photo===photoIndex);const cs=a.contributions.filter(c=>c.photo===photoIndex&&c.status==='approved');return `<div id="book" class="book"><section class="book-page photo"><div class="book-photo"><span class="tape"></span><img src="${esc(p.src)}" alt="${esc(p.alt)}"></div><div class="page-number">${formattedDate(a.date)} · ${esc(a.theme.split(',')[0])}</div></section><section class="book-page story"><div class="story-heading"><span class="eyebrow">${esc(a.title)}</span><button class="icon-btn favorite ${marked?'on':''}" data-action="bookmark" aria-label="${marked?'Remove':'Add'} page bookmark" aria-pressed="${marked}">${icon('bookmark')}</button></div><h2>${esc(p.title)}</h2><p class="story-copy">${esc(p.caption||'A moment worth remembering.')}</p>${audioBlock(a,p,photoIndex)}${cs.map(c=>contributionHTML(a,c)).join('')}<button class="text-link" style="margin-top:22px" data-action="contribute">${icon('mic')}Tell your side of the story</button></section></div><div class="book-controls"><button data-action="prev" aria-label="Previous page" ${photoIndex===0?'disabled':''}>${icon('back')}</button><span class="pagination">${String(photoIndex+1).padStart(2,'0')} / ${String(a.photos.length).padStart(2,'0')}</span><button data-action="next" aria-label="Next page" ${photoIndex===a.photos.length-1?'disabled':''}>${icon('arrow')}</button></div><div class="book-hint">Swipe or use ← → to turn a page · Tap ${icon('play')} to hear a story${a.bookmarks.some(b=>b.account===account)?`<br><button class="text-link" style="margin-top:12px" data-action="bookmarks">${icon('bookmark')}Your bookmarked pages</button>`:''}</div>`}
function connectionsView(){return `<div class="content"><div class="intro-row"><div><div class="eyebrow">Close, even from far away</div><h1>The people in your stories.</h1><p>A small, intentional circle. The right memories, with the right people.</p></div></div><div class="notice-bar">Prototype accounts and devices are preconfigured for your video. Audience settings are applied locally; there are no real invitations, accounts, or connected iPads.</div><div class="two-col"><section class="panel"><div class="eyebrow">Your circle</div><h2 style="margin-top:10px">Faces that feel like home</h2>${Object.entries(people).map(([id,p])=>`<div class="person-row"><span class="avatar">${p.initial}</span><div class="info"><strong>${p.name}</strong><p>${p.role} · Demo PIN ${p.pin}</p></div><button class="btn ghost" data-action="account" data-person="${id}">${id===account?'Current viewer':'Sign in'}</button></div>`).join('')}</section><section class="panel"><div class="eyebrow">Connected album displays</div><h2 style="margin-top:10px">A place for your memories</h2>${Object.entries(deviceNames).map(([id,name])=>`<div class="person-row"><span class="device-icon">${icon('tablet')}</span><div class="info"><strong>${name}</strong><p>${data.albums.filter(a=>canSee(a)&&a.devices.includes(id)).length} visible albums · Simulated connection</p></div><span class="status-dot"></span></div>`).join('')}<p class="note" style="margin-top:20px">An album needs both viewer permission and display permission to appear. Enable a display inside an album’s “Share & devices” settings.</p></section></div><section class="panel" style="margin-top:24px"><h3>Your memories stay yours.</h3><p class="muted" style="font-size:12px;line-height:1.8">Export a full backup with photographs and recordings, or print an individual album as a photo book. Restoring a backup adds albums to this browser and keeps their saved audience settings.</p><div class="action-row">${owner()?`<button class="btn" data-action="backup">${icon('download')}Export all memories</button><label class="btn file-label">${icon('upload')}Restore a backup<input class="sr-input" id="restore-file" type="file" accept="application/json,.json"></label>`:'<span class="note">The album owner manages full-library backups. You can export an album shared with you from its detail page.</span>'}</div></section></div>`}
function guideView(){return `<div class="content"><div class="intro-row"><div><div class="eyebrow">From concept to a shared moment</div><h1>Two celebrations. One keepsake.</h1><p>A complete walkthrough for your three-minute prototype video.</p></div><button class="btn primary" data-action="navigate" data-view="library">${icon('book')}Start exploring</button></div><div class="two-col"><div class="step-list"><article><h3>Curate a birthday</h3><p>As Emma (PIN 1111), choose “Create an album”. Pick birthday photographs, name the album, add a caption and record a voice note. New albums begin private.</p></article><article><h3>Choose who belongs</h3><p>Share with the Family circle and authorise the Family living room iPad. Save, then open the tabletop album. Your changes appear in the same local dataset.</p></article><article><h3>Hear it, together</h3><p>Sign in as Mei (PIN 2468). Open the birthday album, turn a page, play a story and bookmark a photograph. Submit Mum’s perspective; switch to Emma to approve it.</p></article><article><h3>A different audience</h3><p>Share “Graduation 2026” with Alex and the Friends’ shared iPad. Sign in as Alex (PIN 1357). Graduation appears; the family birthday does not. Show both views in your video.</p></article></div><div><section class="panel"><h2>What works in this prototype?</h2><table class="help-table"><thead><tr><th>Experience</th><th>Implementation</th></tr></thead><tbody><tr><td>Curate & retrieve</td><td>Upload / select photos, titles, dates, tags, search and favourites.</td></tr><tr><td>Preserve the story</td><td>Per-photo captions, recording / audio upload, and playback. Sample narration uses your browser’s generated voice.</td></tr><tr><td>Choose an audience</td><td>Private, family or selected friends; viewer and device filtering in both interfaces.</td></tr><tr><td>Revisit & contribute</td><td>Book pages, swipe / keyboard navigation, bookmarks, attributed stories and owner approval.</td></tr><tr><td>Keep & take with you</td><td>IndexedDB persistence, JSON backup / restore and printable photo-book export.</td></tr></tbody></table><p class="note">This is an interaction prototype. The browser is the data store. Switching views simulates a connected display; opening this website on another device does not transfer your data. Demo PINs are a storytelling aid, not production authentication.</p></section><section class="panel" style="margin-top:24px"><h3>Made for your iPad</h3><p class="muted" style="font-size:12px;line-height:1.9">Open the website in Safari, rotate to landscape and choose Tabletop album. A book-style iPad case helps convey the physical album experience. Audio recording needs microphone permission on HTTPS or localhost. Audio-file upload is available as an alternative.</p><p class="muted" style="font-size:12px;line-height:1.9">Before sharing real photographs or voices, check that the people involved agree to the chosen audience. In a production version, accounts, authorisation, cloud storage, device pairing and encryption would require a backend.</p></section></div></div></div>`}
function openModal(type,title,subtitle,body,footer='',large=false){stopPlayback();modalType=type;document.body.classList.add('modal-open');$('#modal-root').innerHTML=`<div class="overlay"><section class="dialog ${large?'large':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1"><header class="dialog-head"><div><div class="eyebrow">Keepsake · A story worth keeping</div><h2 id="modal-title">${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button class="icon-btn" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></header><div class="dialog-body">${body}</div>${footer?`<footer class="dialog-footer">${footer}</footer>`:''}</section></div>`;$('.dialog').focus();}
function recordingButtonIdle(message){
 const button=$('#record-button');
 if(button){button.disabled=false;button.classList.remove('recording');button.innerHTML=icon('mic')+(audioDraft?'Record again':'Record voice');}
 if(message&&$('#record-status'))$('#record-status').textContent=message;
}
function stopRecording(){
 clearInterval(recordTimer);recordTimer=null;
 if(recordPhase==='requesting'){recordingEpoch++;recordPhase='idle';recordProcessing=false;recordingButtonIdle();}
 if(recorder?.state==='recording'){
  recordPhase='stopping';recordProcessing=true;
  const button=$('#record-button');
  if(button){button.disabled=true;button.classList.remove('recording');button.innerHTML=icon('mic')+'Preparing audio…';}
  if($('#record-status'))$('#record-status').textContent='Recording stopped. Preparing your audio…';
  try{recorder.stop();}catch(e){recordPhase='idle';recordProcessing=false;recordingButtonIdle('Recording could not be saved. Please try again.');}
 }
 if(recordStream)recordStream.getTracks().forEach(t=>t.stop());recordStream=null;
}
function closeModal(){recordingEpoch++;recordProcessing=false;stopRecording();modalType=null;$('#modal-root').innerHTML='';document.body.classList.remove('modal-open')}
function validation(msg){const el=$('#validation');if(el){el.textContent=msg;el.focus()}else toast(msg)}
function accountModal(id){const chosen=id||account;openModal('account','Who’s opening the album?','Sign in to a demo viewer. Each person sees only their shared memories.',`${Object.entries(people).map(([id,p])=>`<label class="viewer-card ${id===chosen?'selected':''}"><input type="radio" name="viewer" value="${id}" ${id===chosen?'checked':''}><span class="avatar">${p.initial}</span><div><b>${p.name}</b><small>${p.role} · Demo PIN: ${p.pin}</small></div></label>`).join('')}<label class="field" style="margin-top:22px"><span>Demo PIN</span><input id="viewer-pin" inputmode="numeric" type="password" autocomplete="off" maxlength="4" placeholder="Enter the selected viewer’s 4-digit PIN"><small>Public demo credentials only. This does not secure browser data.</small></label><p id="validation" class="error-text validation" role="alert"></p>`,`<button class="btn ghost" data-action="close-modal">Cancel</button><button class="btn primary" data-action="sign-in">${icon('lock')}Open my memories</button>`)}
function selectedAudienceUI(a){
 const choices=group=>memberIds(group).map(id=>{const p=people[id];const checked=a.recipients.includes(id)||(group==='family'&&a.audience!=='family');return `<label class="choice"><input type="checkbox" name="recipient" value="${id}" ${checked?'checked':''}><span class="avatar">${p.initial}</span><div><b>${esc(p.name)}</b><small>${esc(p.role)}</small></div></label>`;}).join('');
 return `<span class="field-label">Who can view this album?</span>${[['private','lock','Only me','A little space just for you.'],['family','users','Family circle','Choose Mum, Dad or Grandma.'],['friends','heart','Selected friends','Choose the friends who belong in this story.']].map(([id,i,t,d])=>`<label class="choice"><input type="radio" name="audience" value="${id}" ${a.audience===id?'checked':''}>${icon(i)}<div><b>${t}</b><small>${d}</small></div></label>`).join('')}<div id="family-choices" ${a.audience!=='family'?'hidden':''}>${choices('family')}</div><div id="friend-choices" ${a.audience!=='friends'?'hidden':''}>${choices('friends')}</div><span class="field-label" style="margin-top:24px">Which physical displays can show it?</span>${Object.entries(deviceNames).map(([id,n])=>`<label class="choice"><input type="checkbox" name="device" value="${id}" ${a.devices.includes(id)?'checked':''}>${icon('tablet')}<div><b>${n}</b><small>Requires viewer permission as well as display access.</small></div></label>`).join('')}<p class="note">Existing albums keep their saved audience. Select new members here to include them. No real invitations or uploads are sent.</p><p id="validation" role="alert" class="error-text validation"></p>`;
}
function getPermissions(){const audience=$('input[name=audience]:checked').value;return {audience,recipients:[...document.querySelectorAll('input[name=recipient]:checked')].map(e=>e.value).filter(id=>people[id]?.group===audience),devices:[...document.querySelectorAll('input[name=device]:checked')].map(e=>e.value)}}
function shareModal(){if(!owner())return;const a=album();openModal('share','Let the right people in.','Your album stays private until you choose an audience.',selectedAudienceUI(a),`<button class="btn ghost" data-action="close-modal">Cancel</button><button class="btn primary" data-action="save-share">${icon('check')}Save permissions</button>`)}
function recordingUI(){return `<span class="field-label">Give this memory a voice</span><div class="record-controls"><button class="btn" data-action="record" id="record-button">${icon('mic')}Record voice</button><label class="btn file-label">${icon('upload')}Upload audio<input type="file" id="audio-file" class="sr-input" accept="audio/*"></label><button class="btn ghost" data-action="clear-audio">Clear</button></div><div id="record-status" class="status-text" role="status" style="margin:10px 0">${audioDraft?'A saved recording is attached.':audioVoice?'Demo generated narration is attached.':'Optional · up to 60 seconds · microphone permission required'}</div><div id="audio-preview">${audioDraft?`<audio controls src="${esc(audioDraft)}" style="width:100%"></audio>`:''}</div><label class="choice" style="margin-top:12px"><input type="checkbox" id="demo-voice" ${audioVoice?'checked':''}><div><b>Use generated demo narration</b><small>Reads your caption aloud with the browser’s voice. This is not a real voice recording.</small></div></label>`}
function editStoryModal(){if(!owner())return;const a=album(),p=a.photos[photoIndex];audioDraft=p.audio;audioVoice=p.voice;openModal('story','What made this moment yours?','Add context that the photograph can’t tell on its own.',`<label class="field"><span>Photo title</span><input id="photo-title" maxlength="100" value="${esc(p.title)}"></label><div class="prompt-row">${['What happened that day?','Who made this moment special?','What do you want to remember?'].map(t=>`<button data-action="prompt" data-prompt="${t}">${t}</button>`).join('')}</div><label class="field"><span>The story behind the photograph</span><textarea id="story-text" maxlength="5000">${esc(p.caption)}</textarea></label>${recordingUI()}<p class="error-text validation" id="validation" role="alert"></p>`,`<button class="btn ghost" data-action="close-modal">Cancel</button><button class="btn primary" data-action="save-story">Save this story ${icon('arrow')}</button>`)}
function createAlbum(){if(!owner())return;draft={id:uid(),title:'',date:new Date().toLocaleDateString('en-CA'),description:'',theme:'',audience:'private',recipients:[],devices:[],favorite:false,photos:[],contributions:[],bookmarks:[]};audioDraft=null;audioVoice=false;wizardStep=0;wizardModal()}
function wizardModal(){const subtitles=['Choose a few photographs that hold a little more meaning.','Save the feeling behind the first photograph. You can edit each page later.','Every album starts private. Decide who belongs in this story.'];let body=`<div class="progress">${[0,1,2].map(i=>`<span class="${i<=wizardStep?'done':''}"></span>`).join('')}</div><p class="eyebrow" style="margin:18px 0">Step ${wizardStep+1} of 3 · ${['Curate','Tell the story','Share thoughtfully'][wizardStep]}</p>`;
 if(wizardStep===0)body+=`<label class="upload-zone">${icon('upload')}Choose photographs from your device<small>JPEG, PNG or WebP · up to 12 photographs · resized locally</small><input class="sr-input" id="photo-files" type="file" accept="image/jpeg,image/png,image/webp" multiple></label><div class="field-label" style="margin-top:20px">Or start with our sample moments</div><div class="photo-picker">${assets.map(p=>`<button class="pick-photo ${draft.photos.some(q=>q.id===p.id)?'selected':''}" data-action="pick" data-photo="${p.id}" aria-label="Select ${esc(p.alt)}" aria-pressed="${draft.photos.some(q=>q.id===p.id)}"><img src="${p.src}" alt="${esc(p.alt)}"></button>`).join('')}</div><div id="upload-thumbs" class="thumb-row">${draft.photos.filter(p=>!assets.some(a=>a.id===p.id)).map(p=>`<button class="thumb selected" data-action="remove-upload" data-photo="${p.id}" aria-label="Remove ${esc(p.title)}"><img src="${esc(p.src)}" alt="${esc(p.alt)}"></button>`).join('')}</div><p class="status-text" id="selection-count">${draft.photos.length} photographs selected</p>`;
 if(wizardStep===1)body+=`<div class="two-col" style="gap:15px"><label class="field"><span>Album title *</span><input id="album-title" value="${esc(draft.title)}" maxlength="100" placeholder="e.g. My Birthday"></label><label class="field"><span>Date *</span><input type="date" id="album-date" value="${esc(draft.date)}"></label></div><label class="field"><span>A little introduction</span><input id="album-desc" value="${esc(draft.description)}" maxlength="500" placeholder="What holds these moments together?"></label><label class="field"><span>People, places and themes</span><input id="album-theme" value="${esc(draft.theme)}" maxlength="200" placeholder="Family, Birthday, Melbourne"></label><div class="prompt-row"><button data-action="prompt" data-prompt="What made this moment special?">What made this moment special?</button><button data-action="prompt" data-prompt="Who was there with you?">Who was there with you?</button></div><label class="field"><span>Story for your first photograph</span><textarea id="story-text" maxlength="5000" placeholder="This was my first birthday back home in two years…">${esc(draft.photos[0].caption||'')}</textarea></label>${recordingUI()}`;
 if(wizardStep===2)body+=selectedAudienceUI(draft);
 body+='<p class="error-text validation" role="alert" id="validation"></p>';
 openModal('wizard',['A few moments, worth keeping.','Every photo has a story.','Keep it close. Share with care.'][wizardStep],subtitles[wizardStep],body,`<button class="btn ghost" data-action="${wizardStep?'wizard-back':'close-modal'}">${wizardStep?'Back':'Cancel'}</button><button class="btn primary" data-action="wizard-next">${wizardStep===2?'Save my album':'Continue'} ${icon(wizardStep===2?'check':'arrow')}</button>`,true)
}
function captureStoryStep(){draft.title=$('#album-title').value.trim();draft.date=$('#album-date').value;draft.description=$('#album-desc').value.trim();draft.theme=$('#album-theme').value.trim();draft.photos[0].caption=$('#story-text').value.trim();draft.photos[0].audio=audioDraft;draft.photos[0].voice=$('#demo-voice').checked;}
function editAlbumModal(){if(!owner())return;const a=album();openModal('album','Give this chapter a name.','Make your memories easier to find and revisit.',`<label class="field"><span>Album title</span><input id="album-title" maxlength="100" value="${esc(a.title)}"></label><label class="field"><span>Date</span><input type="date" id="album-date" value="${esc(a.date)}"></label><label class="field"><span>Introduction</span><textarea id="album-desc" maxlength="500">${esc(a.description)}</textarea></label><label class="field"><span>People, places and themes</span><input id="album-theme" maxlength="200" value="${esc(a.theme)}"></label><p class="error-text validation" role="alert" id="validation"></p>`,`<button class="btn ghost" data-action="close-modal">Cancel</button><button class="btn primary" data-action="save-album">Save changes</button>`)}
function contributionModal(){const a=album();if(!a||!canSee(a))return;audioDraft=null;audioVoice=false;openModal('contribute','Your side of the story.','A memory can mean something different to everyone who was there.',`<div class="receipt">Contributing as <b>${people[account].name}</b><br>${esc(a.title)} · Photograph ${photoIndex+1}</div><label class="field"><span>What do you remember?</span><textarea id="story-text" maxlength="5000" placeholder="I remember how we all felt that day…"></textarea></label>${recordingUI()}<p class="note">Your name stays with your story. ${owner()?'As the owner, you can add your story directly.':'Emma reviews contributions before they appear in the shared album.'}</p><p class="error-text validation" role="alert" id="validation"></p>`,`<button class="btn ghost" data-action="close-modal">Cancel</button><button class="btn primary" data-action="submit-contribution">${owner()?'Add my story':'Send for approval'} ${icon('arrow')}</button>`)}
function exportModal(){const a=album();openModal('export','A keepsake to take with you.','Keep a portable copy of this album, its stories and its voices.',`<div class="receipt"><b>${esc(a.title)}</b><br>${a.photos.length} photographs · ${a.contributions.filter(c=>c.status==='approved').length} shared contributions</div><p class="muted" style="font-size:12px;line-height:1.9">The JSON backup includes image and audio data. Print creates a photo-book layout; choose “Save as PDF” in your browser. Audio is preserved in JSON, not on paper.</p><div class="action-row"><button class="btn primary" data-action="export-json">${icon('download')}Download album backup</button><button class="btn" data-action="print">${icon('print')}Print photo book</button></div><p class="note">Exported copies can be opened outside this prototype. Share them thoughtfully; changing permissions here cannot revoke a downloaded copy.</p>`)}
async function startRecording(){
 if(recordPhase==='recording'){stopRecording();return;}
 if(recordPhase!=='idle'||recordProcessing)return;
 if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){validation('Recording is not available here. Use Upload audio, or open this page on HTTPS / localhost.');return;}
 const epoch=++recordingEpoch,destination=modalType;
 recordPhase='requesting';recordProcessing=true;
 const button=$('#record-button');if(button){button.disabled=true;button.innerHTML=icon('mic')+'Opening microphone…';}
 let stream,session;
 try{
  stream=await navigator.mediaDevices.getUserMedia({audio:true});
  if(epoch!==recordingEpoch||modalType!==destination||!modalType){stream.getTracks().forEach(t=>t.stop());return;}
  recordStream=stream;const chunks=[];session=new MediaRecorder(stream);recorder=session;
  const isCurrent=()=>epoch===recordingEpoch&&modalType===destination;
  const release=()=>{stream.getTracks().forEach(t=>t.stop());if(recorder===session){clearInterval(recordTimer);recordTimer=null;recordStream=null;recorder=null;recordPhase='idle';recordProcessing=false;if(modalType===destination)recordingButtonIdle();}};
  session.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};
  session.onstop=async()=>{
   try{
    if(!isCurrent())return;
    recordProcessing=true;
    const blob=new Blob(chunks,{type:session.mimeType||'audio/webm'});
    if(!blob.size)throw Error('No audio was captured. Please record again.');
    if(blob.size>8*1024*1024)throw Error('Recording is too large. Please record a shorter clip.');
    const result=await readDataURL(blob);
    if(!isCurrent())return;
    audioDraft=result;audioVoice=false;
    if($('#demo-voice'))$('#demo-voice').checked=false;
    if($('#audio-preview'))$('#audio-preview').innerHTML=`<audio controls src="${esc(audioDraft)}" style="width:100%"></audio>`;
    recordingButtonIdle('Recording stopped · audio attached. Play it below, then save.');
   }catch(e){if(isCurrent()){recordingButtonIdle('Recording stopped. Audio could not be attached.');validation(e.message||'Could not prepare this recording. Please try again.');}}
   finally{release();if(isCurrent())recordingButtonIdle();}
  };
  session.onerror=()=>{if(!isCurrent()){release();return;}recordingEpoch++;release();recordingButtonIdle('Recording stopped because of a microphone error.');validation('Could not record audio. Please try again or upload an audio file.');};
  session.start();recordPhase='recording';recordProcessing=false;recordSeconds=0;
  if(button){button.disabled=false;button.classList.add('recording');button.innerHTML=icon('pause')+'Stop recording';}
  if($('#record-status'))$('#record-status').textContent='Recording… 0s / 60s';
  recordTimer=setInterval(()=>{if(!isCurrent()||session.state!=='recording')return;recordSeconds++;if($('#record-status'))$('#record-status').textContent=`Recording… ${recordSeconds}s / 60s`;if(recordSeconds>=60)stopRecording();},1000);
 }catch(e){
  if(stream)stream.getTracks().forEach(t=>t.stop());
  if(epoch!==recordingEpoch)return;
  clearInterval(recordTimer);recordTimer=null;recordStream=null;recorder=null;recordPhase='idle';recordProcessing=false;
  recordingButtonIdle('Microphone unavailable. You can upload an audio file instead.');
  validation('Microphone access was not granted or is unavailable. You can upload an audio file instead.');
 }
}
const readDataURL=file=>new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.readAsDataURL(file)});
async function resizePhoto(file){if(file.size>20*1024*1024)throw Error('Please choose images smaller than 20 MB.');const src=await readDataURL(file);const image=await new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=()=>reject(Error('This image format could not be opened. Try a JPEG or PNG.'));i.src=src});const scale=Math.min(1,1600/Math.max(image.width,image.height));const canvas=document.createElement('canvas');canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);return {id:uid(),src:canvas.toDataURL('image/jpeg',.82),alt:file.name,title:file.name.replace(/\.[^.]+$/,''),caption:'',audio:null,voice:false}}
function stopPlayback(){if(activeAudio){activeAudio.pause();activeAudio=null}if(window.speechSynthesis)speechSynthesis.cancel();if(currentPlayButton){currentPlayButton.innerHTML=icon('play');currentPlayButton.setAttribute('aria-label','Play story');currentPlayButton=null}}
async function playStory(button){if(currentPlayButton===button){stopPlayback();return}stopPlayback();const a=data.albums.find(a=>a.id===button.dataset.album);if(!a||!canSee(a)||(view==='tabletop'&&!canTable(a)))return;const obj=button.dataset.contribution?a.contributions.find(c=>c.id===button.dataset.contribution):a.photos[+button.dataset.index];if(!obj)return;if(obj.status==='pending'&&!owner())return;currentPlayButton=button;button.innerHTML=icon('pause');button.setAttribute('aria-label','Stop story');if(obj.audio){activeAudio=new Audio(obj.audio);activeAudio.onended=stopPlayback;activeAudio.onerror=()=>{stopPlayback();toast('Audio could not be played. Try a different recording format.')};try{await activeAudio.play()}catch(e){stopPlayback();toast('Tap again to play audio, or try another audio format.')}}else if(window.speechSynthesis){const text=obj.text||obj.caption;if(!text){stopPlayback();toast('Add a caption before playing generated narration.');return}const speech=new SpeechSynthesisUtterance(text);speech.lang='en-AU';speech.rate=.88;speech.onend=stopPlayback;speech.onerror=()=>{stopPlayback();toast('Generated voice is unavailable on this browser. Upload a recording instead.')};speechSynthesis.speak(speech)}else{stopPlayback();toast('Generated voice is unavailable. Use a recorded voice note.')}}
function attachSwipe(){let x=0,y=0;const b=$('#book');b.addEventListener('touchstart',e=>{x=e.changedTouches[0].clientX;y=e.changedTouches[0].clientY},{passive:true});b.addEventListener('touchend',e=>{const dx=e.changedTouches[0].clientX-x,dy=e.changedTouches[0].clientY-y;if(Math.abs(dx)>65&&Math.abs(dx)>Math.abs(dy)*1.4)turnPage(dx<0?1:-1)},{passive:true})}
function turnPage(direction){if(modalType||view!=='tabletop'||!currentId)return;const a=album();if(!a||!canTable(a))return;const next=photoIndex+direction;if(next<0||next>=a.photos.length)return;photoIndex=next;render()}
async function exportAlbums(albums,filename){try{toast('Preparing a portable copy…');const portable=await Promise.all(albums.map(async a=>({...a,contributions:a.contributions.filter(c=>owner()||c.status==='approved'),photos:await Promise.all(a.photos.map(async p=>{if(p.src.startsWith('data:'))return p;const res=await fetch(p.src);if(!res.ok)throw Error('Image unavailable');return {...p,src:await readDataURL(await res.blob())}}))})));download(JSON.stringify({format:'keepsake-album',version:1,exportedAt:new Date().toISOString(),albums:portable},null,2),filename,'application/json');toast('Your portable backup is ready.')}catch(e){toast('An image could not be included. Check your connection and try again.')}}
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000)}
function printAlbum(){const a=album();closeModal();const section=document.createElement('div');section.className='print-only';section.id='print-album';section.innerHTML=a.photos.map((p,i)=>`<section class="print-page"><div class="eyebrow">${formattedDate(a.date)} · ${audienceName(a)} · ${i+1}/${a.photos.length}</div><h1>${esc(a.title)}</h1><img src="${esc(p.src)}" alt="${esc(p.alt)}"><h2>${esc(p.title)}</h2><p>${esc(p.caption)}</p>${a.contributions.filter(c=>c.status==='approved'&&c.photo===i).map(c=>`<p><b>${esc(people[c.author]?.name||c.author)}</b>: ${esc(c.text)}</p>`).join('')}<small>Keepsake · Every photo has a story worth keeping.</small></section>`).join('');document.body.append(section);const style=document.createElement('style');style.textContent='@media print{#app{display:none!important}#print-album{display:block}}';document.head.append(style);const cleanup=()=>{section.remove();style.remove();window.removeEventListener('afterprint',cleanup)};window.addEventListener('afterprint',cleanup);Promise.all([...section.querySelectorAll('img')].map(i=>i.decode().catch(()=>{}))).then(()=>window.print())}
function validateBackup(obj){if(obj?.format!=='keepsake-album'||obj.version!==1||!Array.isArray(obj.albums)||!obj.albums.length||obj.albums.length>100)throw Error('Choose a Keepsake version 1 backup with 1–100 albums.');return obj.albums.map(a=>{if(!a||typeof a.title!=='string'||!a.title.trim()||!/^\d{4}-\d{2}-\d{2}$/.test(a.date)||!Number.isFinite(Date.parse(a.date))||!Array.isArray(a.photos)||!a.photos.length||a.photos.length>12)throw Error('The backup contains an incomplete album.');const media=(s,kind)=>s===null||s===undefined?null:typeof s==='string'&&(kind==='image'?/^data:image\/(jpeg|png|webp);base64,/.test(s):/^data:audio\/[\w.+-]+(?:;[^,]*)?;base64,/.test(s))?s:(()=>{throw Error('Unsupported media in backup. Use a backup exported from Keepsake.')})();const photos=a.photos.map(p=>({id:uid(),src:media(p.src,'image'),alt:String(p.alt||'Memory photograph').slice(0,300),title:String(p.title||'A moment to keep').slice(0,100),caption:String(p.caption||'').slice(0,5000),audio:media(p.audio,'audio'),voice:!!p.voice}));if(photos.some(p=>!p.src))throw Error('A photograph is missing from this backup.');return {id:uid(),title:a.title.slice(0,100),date:a.date,description:String(a.description||'').slice(0,500),theme:String(a.theme||'').slice(0,200),audience:['private','family','friends'].includes(a.audience)?a.audience:'private',recipients:Array.isArray(a.recipients)?a.recipients.filter(id=>people[id]?.group===a.audience&&id!=='emma'):[],devices:Array.isArray(a.devices)?a.devices.filter(id=>['family','friends'].includes(id)):[],favorite:!!a.favorite,photos,contributions:(Array.isArray(a.contributions)?a.contributions:[]).slice(0,100).filter(c=>Object.hasOwn(people,c.author)&&Number.isInteger(c.photo)&&c.photo>=0&&c.photo<photos.length).map(c=>({id:uid(),author:c.author,photo:c.photo,text:String(c.text||'').slice(0,5000),audio:media(c.audio,'audio'),voice:!!c.voice,status:['approved','pending','declined'].includes(c.status)?c.status:'pending'})),bookmarks:(Array.isArray(a.bookmarks)?a.bookmarks:[]).filter(b=>people[b.account]&&Number.isInteger(b.photo)&&b.photo>=0&&b.photo<photos.length)}})}
document.addEventListener('click',async e=>{const button=e.target.closest('[data-action]');if(!button||button.disabled)return;const action=button.dataset.action,a=album();if(busy&&!['close-modal'].includes(action))return;
 if(action==='focus-mode'){immersive=!immersive;render();return}
 if(['save-story','wizard-next','wizard-back','submit-contribution'].includes(action)&&recordProcessing){validation('Your recording is being prepared. Please try again in a moment.');return}
 if(action==='navigate'){closeModal();view=button.dataset.view;currentId=null;query='';render();return}
 if(action==='close-modal'){closeModal();return}
 if(action==='account'){accountModal(button.dataset.person);return}
 if(action==='sign-in'){const id=$('input[name=viewer]:checked').value;if($('#viewer-pin').value!==people[id].pin){validation('That PIN does not match. Use the demo PIN shown beside this viewer.');return}account=id;tabletopDevice=viewerDevice(id);currentId=null;filter='all';query='';closeModal();render();toast(`Welcome, ${people[id].name}. Your view is ready.`);return}
 if(action==='filter'){filter=button.dataset.filter;render();return}
 if(action==='create'){createAlbum();return}
 if(action==='open'){const target=data.albums.find(a=>a.id===button.dataset.id);if(!target||!canSee(target)||(view==='tabletop'&&!canTable(target))){toast('This viewer or display does not have access.');return}currentId=target.id;photoIndex=0;render();return}
 if(action==='back-library'||action==='table-library'){currentId=null;render();return}
 if(action==='favorite'){const target=data.albums.find(a=>a.id===button.dataset.id);if(!target||!canSee(target))return;target.favorite=!target.favorite;await save();render();return}
 if(action==='table-open'){if(!a?.devices.length){toast('Enable a physical display in Share & devices first.');return}if(!owner()&&!a.devices.includes(tabletopDevice)){toast('This album is not authorised for your display.');return}if(owner()&&!a.devices.includes(tabletopDevice))tabletopDevice=a.devices[0];view='tabletop';render();return}
 if(action==='photo'){photoIndex=+button.dataset.index;render();return}
 if(action==='share'){shareModal();return}
 if(action==='save-share'){if(!owner()||!a)return;const p=getPermissions();if(p.audience!=='private'&&!p.recipients.length){validation('Choose at least one person, or keep the album private.');return}Object.assign(a,p);const ok=await save();closeModal();render();if(ok)toast('Permissions saved. The tabletop view has been updated locally.');return}
 if(action==='edit-story'){editStoryModal();return}
 if(action==='record'){await startRecording();return}
 if(action==='clear-audio'){recordingEpoch++;stopRecording();audioDraft=null;audioVoice=false;$('#demo-voice').checked=false;$('#audio-preview').innerHTML='';$('#record-status').textContent='Audio removed. Save to apply this change.';return}
 if(action==='prompt'){const input=$('#story-text');if(input){input.placeholder=button.dataset.prompt;input.focus()}return}
 if(action==='save-story'){if(!owner()||!a)return;if(recorder?.state==='recording'){validation('Stop recording before saving.');return}const title=$('#photo-title').value.trim();if(!title){validation('Give this photograph a short title.');return}Object.assign(a.photos[photoIndex],{title,caption:$('#story-text').value.trim(),audio:audioDraft,voice:$('#demo-voice').checked});const ok=await save();closeModal();render();if(ok)toast('Your story is saved, ready to revisit.');return}
 if(action==='edit-album'){editAlbumModal();return}
 if(action==='save-album'){if(!owner()||!a)return;const title=$('#album-title').value.trim(),date=$('#album-date').value;if(!title||!date){validation('Add an album title and date.');return}Object.assign(a,{title,date,description:$('#album-desc').value.trim(),theme:$('#album-theme').value.trim()});await save();closeModal();render();return}
 if(action==='pick'){const p=assets.find(p=>p.id===button.dataset.photo);const i=draft.photos.findIndex(p=>p.id===button.dataset.photo);if(i>=0)draft.photos.splice(i,1);else if(draft.photos.length<12)draft.photos.push({...p,caption:'',audio:null,voice:false});else{toast('Choose up to 12 meaningful photographs.');return}button.classList.toggle('selected',draft.photos.some(q=>q.id===p.id));button.setAttribute('aria-pressed',String(draft.photos.some(q=>q.id===p.id)));$('#selection-count').textContent=`${draft.photos.length} photographs selected`;return}
 if(action==='remove-upload'){draft.photos=draft.photos.filter(p=>p.id!==button.dataset.photo);wizardModal();return}
 if(action==='wizard-back'){if(recorder?.state==='recording'){validation('Stop recording before changing steps.');return}if(wizardStep===1)captureStoryStep();if(wizardStep===2)Object.assign(draft,getPermissions());wizardStep--;wizardModal();return}
 if(action==='wizard-next'){if(wizardStep===0){if(!draft.photos.length){validation('Choose at least one photograph to begin.');return}wizardStep++;wizardModal();return}if(wizardStep===1){if(recorder?.state==='recording'){validation('Stop recording before continuing.');return}captureStoryStep();if(!draft.title||!draft.date){validation('Add a title and date for your album.');return}wizardStep++;wizardModal();return}const p=getPermissions();if(p.audience!=='private'&&!p.recipients.length){validation('Choose at least one person, or keep this album private.');return}Object.assign(draft,p);data.albums.unshift(draft);currentId=draft.id;photoIndex=0;filter='all';query='';const ok=await save();closeModal();render();if(ok)toast('A new chapter, lovingly saved.');return}
 if(action==='contribute'){contributionModal();return}
 if(action==='submit-contribution'){if(!a||!canSee(a))return;if(recorder?.state==='recording'){validation('Stop recording before sending your story.');return}const text=$('#story-text').value.trim();if(!text&&!audioDraft){validation('Write a memory or attach a voice recording.');return}a.contributions.push({id:uid(),photo:photoIndex,author:account,text,audio:audioDraft,voice:$('#demo-voice').checked,status:owner()?'approved':'pending'});const ok=await save();closeModal();render();if(ok)toast(owner()?'Your perspective is part of this memory.':'Your story was submitted locally. Switch to Emma to review it.');return}
 if(action==='approve'||action==='decline'||action==='withdraw'){if(!a||!canSee(a))return;const c=a.contributions.find(c=>c.id===button.dataset.contribution);if(!c)return;if(action!=='withdraw'&&!owner())return;if(action==='withdraw'&&!owner()&&c.author!==account)return;c.status=action==='approve'?'approved':'declined';await save();render();toast(action==='approve'?'Story approved. It now appears in the shared album.':'Story removed from the shared album.');return}
 if(action==='play'){await playStory(button);return}
 if(action==='next'||action==='prev'){turnPage(action==='next'?1:-1);return}
 if(action==='bookmark'){if(!a||!canTable(a))return;const idx=a.bookmarks.findIndex(b=>b.account===account&&b.photo===photoIndex);if(idx>=0)a.bookmarks.splice(idx,1);else a.bookmarks.push({account,photo:photoIndex});await save();render();return}
 if(action==='bookmarks'){if(!a||!canTable(a))return;openModal('bookmarks','Pages you come back to.','Your bookmarks belong to your viewer profile.',a.bookmarks.filter(b=>b.account===account).map(b=>`<button class="choice" style="width:100%;text-align:left" data-action="jump-bookmark" data-index="${b.photo}">${icon('bookmark')}<div><b>${esc(a.photos[b.photo].title)}</b><small>Page ${b.photo+1} · ${esc(a.title)}</small></div>${icon('arrow')}</button>`).join(''));return}
 if(action==='jump-bookmark'){photoIndex=+button.dataset.index;closeModal();render();return}
 if(action==='export'){exportModal();return}
 if(action==='export-json'){if(a&&canSee(a))await exportAlbums([a],a.title.replace(/[^a-z0-9]/gi,'-')+'-keepsake.json');return}
 if(action==='backup'){if(owner())await exportAlbums(data.albums,'my-keepsake-backup.json');return}
 if(action==='print'){if(a&&canSee(a))printAlbum();return}
 if(action==='delete'){if(!owner()||!a)return;openModal('delete','Let this chapter go?','This removes the album, its recordings, bookmarks and contributions from this browser.',`<p class="note">Export a backup first if you want to keep a copy of “${esc(a.title)}”. This action cannot be undone here.</p>`,`<button class="btn ghost" data-action="close-modal">Keep album</button><button class="btn danger" data-action="confirm-delete">Delete album</button>`);return}
 if(action==='confirm-delete'){if(!owner()||!a)return;data.albums=data.albums.filter(x=>x.id!==a.id);currentId=null;await save();closeModal();render();toast('Album deleted from this browser.');return}
});
document.addEventListener('change',async e=>{const input=e.target;if(input.name==='viewer'){document.querySelectorAll('.viewer-card').forEach(c=>c.classList.toggle('selected',c.querySelector('input').checked));$('#viewer-pin').value='';return}if(input.name==='audience'){$('#friend-choices').hidden=input.value!=='friends';$('#family-choices').hidden=input.value!=='family';return}if(input.id==='demo-voice'){audioVoice=input.checked;if(input.checked){recordingEpoch++;stopRecording();audioDraft=null;$('#audio-preview').innerHTML='';$('#record-status').textContent='Generated narration selected. Save to attach it.';}return}if(input.id==='device-select'){tabletopDevice=input.value;currentId=null;render();return}
 if(input.id==='photo-files'){const files=[...input.files];if(files.length+draft.photos.length>12){validation('Select up to 12 photographs in total.');return}busy=true;try{toast('Preparing your photographs locally…');for(const file of files){if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Choose JPEG, PNG or WebP images.');draft.photos.push(await resizePhoto(file))}if(modalType==='wizard')wizardModal();toast(`${draft.photos.length} photographs selected.`)}catch(err){validation(err.message)}finally{busy=false}return}
 if(input.id==='audio-file'){const file=input.files[0];if(!file)return;if(file.size>8*1024*1024||!file.type.startsWith('audio/')){validation('Choose an audio file smaller than 8 MB.');return}try{recordingEpoch++;stopRecording();audioDraft=await readDataURL(file);audioVoice=false;$('#demo-voice').checked=false;$('#audio-preview').innerHTML=`<audio controls src="${esc(audioDraft)}" style="width:100%"></audio>`;$('#record-status').textContent='Audio file attached · ready to save.'}catch(err){validation('Could not read that audio file. Please choose another.')}return}
 if(input.id==='restore-file'){if(!owner())return;const file=input.files[0];if(!file)return;if(file.size>150*1024*1024){toast('Please choose a backup smaller than 150 MB.');return}try{const imported=validateBackup(JSON.parse(await file.text()));data.albums.unshift(...imported);const ok=await save();render();if(ok)toast(`${imported.length} albums restored as new copies.`)}catch(err){toast(err.message||'This backup could not be restored.')}return}
});
document.addEventListener('keydown',e=>{if(modalType){if(e.key==='Escape')closeModal();if(e.key==='Tab'){const items=[...$('.dialog').querySelectorAll('button:not(:disabled), input:not([type=file]), textarea, select, a[href], audio')].filter(el=>el.getClientRects().length);if(items.length){const first=items[0],last=items[items.length-1];if(e.shiftKey&&(document.activeElement===first||document.activeElement===$('.dialog'))){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}}return}if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))return;if(e.key==='ArrowRight'){e.preventDefault();turnPage(1)}if(e.key==='ArrowLeft'){e.preventDefault();turnPage(-1)}});
window.addEventListener('pagehide',()=>{stopPlayback();stopRecording()});
init();

